"""Initialize study cohorts from timestamped field moisture observations."""
from __future__ import annotations
import copy
import math
from .model import World


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError('Supply finite timestamps and moisture percentages')
    return float(value)


def estimate(readings, at):
    if not isinstance(readings, (list, tuple)) or any(not isinstance(row, dict) for row in readings):
        raise ValueError('Supply a list of timestamped moisture readings')
    try:
        values = [(_number(row['timestamp']), _number(row['moisture'])) for row in readings]
    except KeyError as exc:
        raise ValueError('Each reading needs a timestamp and moisture') from exc
    raw_at = at
    at = _number(at)
    if not values or not math.isfinite(at) or any(not math.isfinite(t) or not math.isfinite(y) or not 0 <= y <= 100 for t, y in values):
        raise ValueError('Supply finite timestamps and moisture percentages')
    from fractions import Fraction
    exact = [(Fraction(raw_t), Fraction(raw_y)) for raw_t, raw_y in
             ((row['timestamp'], row['moisture']) for row in readings)]
    grouped = {}
    for t, y in exact:
        grouped.setdefault(t, []).append(y)
    points = sorted((t, sum(ys, Fraction(0))/len(ys)) for t, ys in grouped.items())
    origin = points[0][0]
    offsets = [t - origin for t, _ in points]
    ys = [y for _, y in points]
    center = sum(offsets, Fraction(0))/len(offsets)
    mean = sum(ys, Fraction(0))/len(ys)
    spread = sum(((d - center)*(d - center) for d in offsets), Fraction(0))
    covariance = sum(((d - center)*(y - mean) for d, y in zip(offsets, ys)), Fraction(0))
    slope = covariance/spread if spread > 0 else Fraction(0)
    prediction = float(mean + slope*((Fraction(raw_at)-origin)-center))
    return max(0.0, min(100.0, prediction))


def calibrated_sources(worlds, observations, at):
    if set(worlds) != set(observations):
        raise ValueError('Each garden needs observations')
    sources, receipt = {}, {'at': at, 'observations': copy.deepcopy(observations), 'estimates': {}}
    for label, value in worlds.items():
        original = value.to_dict() if isinstance(value, World) else value
        world = World.from_dict(copy.deepcopy(original))
        moisture = estimate(observations[label], at)
        for cell, tile in zip(world.cells, world.workbench['tiles']):
            if tile['terrain'] == 'pond':
                cell.moisture = 100
            elif tile['terrain'] == 'stone':
                cell.moisture = 0
            else:
                cell.moisture = round(moisture)
        sources[label] = world
        receipt['estimates'][label] = moisture

