import ast, pathlib
for p in sorted(pathlib.Path('mosslight').glob('*.py')):
    tree=ast.parse(p.read_text())
    for fn in ast.walk(tree):
        if isinstance(fn,(ast.FunctionDef,ast.AsyncFunctionDef)):
            assigned={}; used=set()
            params={a.arg for a in fn.args.args+fn.args.kwonlyargs}
            for node in ast.walk(fn):
                if isinstance(node,ast.Name):
                    if isinstance(node.ctx,ast.Store): assigned.setdefault(node.id,node.lineno)
                    else: used.add(node.id)
            for n,l in assigned.items():
                if n not in used and not n.startswith('_'): print(p.name, fn.name, 'unused var', n, l)
            for a in params:
                if a not in used and a not in ('self','cls','format','args','kwargs'): print(p.name, fn.name, 'unused param', a)
